def _normalize_codes(values):
    """Normalize and deduplicate catalog codes in stable order."""
    codes = []
    seen = set()
    for value in values:
        if not isinstance(value, str):
            continue
        code = "_".join(value.split()).upper()[:64]
        if code and code not in seen:
            seen.add(code)
            codes.append(code)
    return codes


def backfill_model_variant_codes(apps, schema_editor):
    """Copy model and variant codes into each model's normalized code list."""
    using = schema_editor.connection.alias
    model_class = apps.get_model("firmwares", "Model")
    variant_class = apps.get_model("firmwares", "Variant")
    model_queryset = model_class.objects.using(using).only(
        "pk", "model_code", "model_codes"
    )
    batch = []

    for model in model_queryset.order_by("pk").iterator(chunk_size=1000):
        batch.append(model)
        if len(batch) == 1000:
            _backfill_batch(model_class, variant_class, batch, using)
            batch.clear()
    if batch:
        _backfill_batch(model_class, variant_class, batch, using)


def _backfill_batch(model_class, variant_class, model_batch, using):
    """Backfill normalized codes for one bounded model batch."""
    variant_codes: dict[int, list[str]] = {}
    rows = (
        variant_class.objects.using(using)
        .filter(model_id__in=[model.pk for model in model_batch])
        .order_by("model_id", "pk")
        .values_list("model_id", "model_code")
    )
    for model_id, code in rows.iterator(chunk_size=1000):
        variant_codes.setdefault(model_id, []).append(code)

    for model in model_batch:
        model.variant_codes = _normalize_codes(
            [
                model.model_code,
                *(model.model_codes or []),
                *variant_codes.get(model.pk, ()),
            ]
        )
    model_class.objects.using(using).bulk_update(
        model_batch, ["variant_codes"], batch_size=1000
    )


